<div class="wrap">
  <h1>Állatok, színek és sulis dolgok</h1>
  <p class="hint">Kattints egy kártyára, hogy megforduljon, és nézd meg az angol szót! Ha helyesen találod ki, kattints a „Találtam!” gombra.</p>

  <div class="scorebar" aria-hidden="true">
    <div class="stat"><div class="k">Talált szavak</div><div class="v accent" id="found">0</div></div>
    <div class="stat"><div class="k">Kártyák</div><div class="v"><span id="total">0</span> / <span id="decksize">0</span></div></div>
    <div class="stat"><div class="k">Sorozat</div><div class="v" id="streak">0</div></div>
  </div>

  <div class="controls">
    <label for="deck">Csomag</label>
    <select id="deck">
      <option value="all">Mind</option>
      <option value="animals">Állatok</option>
      <option value="colors">Színek</option>
      <option value="school">Iskolai dolgok</option>
    </select>
    <label for="lang">Mutassa</label>
    <select id="lang">
      <option value="hu">A magyart</option>
      <option value="en">Az angolt</option>
    </select>
    <button class="btn" id="reset">Újrakezdés</button>
  </div>

  <div id="grid" class="grid"></div>
  <div id="empty" class="empty" hidden>
    <div class="big" id="emptyEmoji" aria-hidden="true">🎉</div>
    <h2 id="emptyTitle">Szép munka!</h2>
    <p id="emptyText">Ezt a csomagot végigcsináltad. Válassz másikat, vagy kezdd újra!</p>
    <button class="btn primary" id="emptyBtn" hidden>Újrakezdés</button>
  </div>
  <p class="sr-only" aria-live="polite" id="live"></p>
</div>

<script>
const WORDS = [
  {en:'cat', hu:'macska', emoji:'🐱', cat:'animals'},
  {en:'dog', hu:'kutya', emoji:'🐶', cat:'animals'},
  {en:'fish', hu:'hal', emoji:'🐟', cat:'animals'},
  {en:'bird', hu:'madár', emoji:'🐦', cat:'animals'},
  {en:'horse', hu:'ló', emoji:'🐴', cat:'animals'},
  {en:'rabbit', hu:'nyúl', emoji:'🐰', cat:'animals'},
  {en:'frog', hu:'béka', emoji:'🐸', cat:'animals'},
  {en:'bee', hu:'méh', emoji:'🐝', cat:'animals'},
  {en:'red', hu:'piros', emoji:'🔴', cat:'colors'},
  {en:'blue', hu:'kék', emoji:'🔵', cat:'colors'},
  {en:'green', hu:'zöld', emoji:'🟢', cat:'colors'},
  {en:'yellow', hu:'sárga', emoji:'🟡', cat:'colors'},
  {en:'orange', hu:'narancs', emoji:'🟠', cat:'colors'},
  {en:'purple', hu:'lila', emoji:'🟣', cat:'colors'},
  {en:'pink', hu:'rózsaszín', emoji:'🌸', cat:'colors'},
  {en:'black', hu:'fekete', emoji:'⚫', cat:'colors'},
  {en:'book', hu:'könyv', emoji:'📖', cat:'school'},
  {en:'pencil', hu:'ceruza', emoji:'✏️', cat:'school'},
  {en:'ruler', hu:'vonalzó', emoji:'📏', cat:'school'},
  {en:'backpack', hu:'táska', emoji:'🎒', cat:'school'},
  {en:'scissors', hu:'olló', emoji:'✂️', cat:'school'},
  {en:'notebook', hu:'füzet', emoji:'📓', cat:'school'},
  {en:'clock', hu:'óra', emoji:'⏰', cat:'school'},
  {en:'globe', hu:'földgömb', emoji:'🌍', cat:'school'}
];
const CATS = {all:'Mind', animals:'Állatok', colors:'Színek', school:'Iskolai dolgok'};
const KEY = 'cards-v1';
const hasStore = !!(window.alfy && window.alfy.storage);

let state = { deck:'all', lang:'hu', solved:{}, streak:0 };
const grid = document.getElementById('grid');
const empty = document.getElementById('empty');
const live = document.getElementById('live');

function save(){ if(hasStore) window.alfy.storage.set(KEY, state); }
function load(){
  if(!hasStore) return;
  window.alfy.storage.get(KEY).then(v => {
    if(v && typeof v === 'object'){
      state.deck = v.deck || 'all';
      state.lang = v.lang || 'hu';
      state.solved = v.solved || {};
      state.streak = v.streak || 0;
    }
    init();
  }).catch(init);
}

function currentDeck(){ return state.deck === 'all' ? WORDS : WORDS.filter(w => w.cat === state.deck); }
function solvedCount(d){ return d.filter(w => state.solved[w.en]).length; }
function announce(msg){ live.textContent = ''; setTimeout(() => { live.textContent = msg; }, 30); }

function render(){
  const d = currentDeck();
  document.getElementById('total').textContent = solvedCount(d);
  document.getElementById('decksize').textContent = d.length;
  document.getElementById('found').textContent = Object.keys(state.solved).length;
  document.getElementById('streak').textContent = state.streak;

  if(d.length === 0){
    grid.innerHTML = '';
    empty.hidden = false;
    document.getElementById('emptyEmoji').classList.remove('hidden');
    document.getElementById('emptyTitle').textContent = 'Nincs kártya ebben a csomagban';
    document.getElementById('emptyText').textContent = 'Válassz másik csomagot.';
    document.getElementById('emptyBtn').hidden = true;
    return;
  }

  const done = solvedCount(d) === d.length;
  empty.hidden = !done;
  document.getElementById('emptyEmoji').classList.toggle('hidden', !done);
  document.getElementById('emptyTitle').textContent = 'Szép munka! 🎉';
  document.getElementById('emptyText').textContent =
    'Végigcsináltad a(z) ' + CATS[state.deck] + ' csomagot ' + d.length + ' kártyából.';
  document.getElementById('emptyBtn').hidden = !done;

  grid.innerHTML = '';
  d.forEach(w => {
    const solved = !!state.solved[w.en];
    const btn = document.createElement('button');
    btn.className = 'card' + (solved ? ' flipped' : '');
    btn.type = 'button';
    btn.setAttribute('aria-pressed', solved ? 'true' : 'false');
    btn.setAttribute('aria-label',
      'Kártya: ' + (state.lang === 'hu' ? w.hu : w.en) + (solved ? ', már megtanultad' : ', kattints a megfordításhoz'));

    const inner = document.createElement('span');
    inner.className = 'card-inner';

    const front = document.createElement('span');
    front.className = 'front';
    const em = document.createElement('span'); em.className = 'emoji'; em.textContent = w.emoji;
    const cat = document.createElement('span'); cat.className = 'cat'; cat.textContent = CATS[w.cat];
    front.append(em, cat);

    const back = document.createElement('span');
    back.className = 'back';
    const en = document.createElement('span'); en.className = 'en'; en.textContent = w.en;
    const hu = document.createElement('span'); hu.className = 'hu'; hu.textContent = w.hu;
    const mark = document.createElement('span'); mark.className = 'mark';
    mark.textContent = solved ? '✓ Megtanultad!' : 'Találtam!';
    back.append(en, hu, mark);

    inner.append(front, back);
    btn.append(inner);
    btn.addEventListener('click', () => toggle(btn, w, solved));
    grid.appendChild(btn);
  });
}

function toggle(btn, w, solved){
  if(solved){
    delete state.solved[w.en];
    state.streak = 0;
    announce(w.en + ' (' + w.hu + ') törölve a tanultak közül.');
  } else {
    state.solved[w.en] = true;
    state.streak += 1;
    announce('Szép! ' + w.en + ' = ' + w.hu + '. Sorozat: ' + state.streak + '.');
  }
  save();
  render();
}

function init(){
  document.getElementById('deck').value = state.deck;
  document.getElementById('lang').value = state.lang;
  document.getElementById('deck').addEventListener('change', e => { state.deck = e.target.value; save(); render(); });
  document.getElementById('lang').addEventListener('change', e => { state.lang = e.target.value; save(); render(); });
  document.getElementById('reset').addEventListener('click', () => {
    state.solved = {}; state.streak = 0; save(); render();
    announce('Újrakezdtem a csomagot.');
  });
  document.getElementById('emptyBtn').addEventListener('click', () => {
    state.solved = {}; state.streak = 0; save(); render();
    announce('Újrakezdtem a csomagot.');
  });
  render();
}

load();
</script>
</body>
